    rate, hours, got = num(r[2]), num(r[3]), num(r[4])
    if rate is None or hours is None or got is None:
        ok = False; break
    want = rate * min(hours, 40) + rate * 1.5 * max(hours - 40, 0)
    if abs(got - round(want, 2)) > 0.005:
        ok = False; break
